#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn from_terms_on_empty_vec_produces_all_empty_fields() {
        let qp = QueryPlan::from_terms(Vec::new());
        assert!(qp.terms.is_empty());
        assert!(qp.required.is_empty());
        assert!(qp.excluded.is_empty());
        assert!(qp.scored.is_empty());
    }

    fn term(modifier: Modifier, pattern: &str) -> ParsedTerm {
        all.sort_unstable();
        assert_eq!(all, vec![0, 1, 2, 3, 4, 5]);
    }

    #[test]
    fn exclusion_only_plan_has_no_search_patterns() {
        let qp = QueryPlan::from_terms(vec![term(Modifier::Excluded, "e0"), term(Modifier::Excluded, "e1")]);
        assert!(qp.search_patterns().is_empty());
    }

    #[test]
    assert!(!accepted);
}

#[test]
fn nothing_the_scan_accepts_overflows_a_stack_sized_for_the_cap() {
    // The check is only worth anything if the child can run: an ordinary file must not count as a crash.
    assert!(crashing(&[(Kind::Ts, "export const a = 1;\n".to_owned())]).is_empty(), "the child process does not run");
    assert!(!crashing(&[(Kind::Ts, format!("{}1{}", "(".repeat(1_000_000), ")".repeat(1_000_000)))]).is_empty());
    let fixed = std::env::var("MONOKL_FUZZ_SEED").ok().and_then(|value| value.parse().ok()).unwrap_or(0x5eed_u64);
    let nanos = std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH).unwrap().as_nanos();
    let random = u64::try_from(nanos % u128::from(u64::MAX)).unwrap();
}

/// Converts a count to `f64`.
#[expect(clippy::cast_precision_loss, reason = "token and document counts stay far below 2^53")]
pub(super) fn as_f64(count: usize) -> f64 {
    count as f64
}

